def recalculate_risk_severity(apps, schema_editor):

    Risk = apps.get_model("compliance", "Risk")

    for risk in Risk.objects.all():
        risk.likelihood = min(max(risk.likelihood, 1), 5)
        risk.impact = min(max(risk.impact, 1), 5)
        score = risk.likelihood * risk.impact
        risk.severity = (
            "extreme" if score >= 15
            else "high" if score >= 10
            else "medium" if score >= 5
            else "low"
        )
        risk.save(update_fields=["likelihood", "impact", "severity"])


